// src/components/FilmGallery.jsx
import React, { useState, useEffect } from 'react';
import FilmCard from './FilmCard';

// Функція для форматування часу у години та хвилини
const formatTime = (totalMinutes) => {
    if (isNaN(totalMinutes) || totalMinutes < 0) return '0h 0m';
    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;
    return `${hours}h ${minutes}m`;
};

function FilmGallery() {
    const [films, setFilms] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [totalTime, setTotalTime] = useState('0h 0m'); // Стан для відображення загального часу
    
    // Стан для сортування (наразі лише заглушка)
    const [sortBy, setSortBy] = useState('length'); 

    // --- ЛОГІКА ЗАВАНТАЖЕННЯ ДАНИХ (Залишається незмінною) ---
    useEffect(() => {
        fetch('/films') 
            .then(response => {
                if (!response.ok) {
                    throw new Error('Failed to fetch films from server.');
                }
                return response.json();
            })
            .then(data => {
                setFilms(data);
                setLoading(false);
            })
            .catch(err => {
                setError("Could not load films from the server. Check if the server is running on port 5000.");
                setLoading(false);
                console.error("Fetch error: ", err);
            });
    }, []);
    // -----------------------------------------------------------

    // --- НОВА ЛОГІКА: Підрахунок загального часу ---
    const handleCountTotalTime = () => {
        // Припускаємо, що властивість часу у ваших фільмах називається 'time' (як у server.js)
        const totalMinutes = films.reduce((sum, film) => sum + (film.time || 0), 0);
        setTotalTime(formatTime(totalMinutes));
    };
    // ----------------------------------------------------

    if (loading) {
        return <h2>Loading films...</h2>;
    }

    if (error) {
        return <h2 style={{ color: 'red' }}>Error: {error}</h2>;
    }

    return (
        <div className="film-list-container">
            {/* --- БЛОК УПРАВЛІННЯ (Manage films) --- */}
            <div className="manage-films-box">
                <h3>Manage films</h3>
                <div className="controls">
                    {/* Сортування */}
                    <label htmlFor="sortBy">Sort by:</label>
                    <select 
                        id="sortBy" 
                        value={sortBy} 
                        onChange={(e) => setSortBy(e.target.value)}
                        className="sort-select"
                    >
                        {/* Зверніть увагу, що у вас на скріншоті було "Lenght" з помилкою */}
                        <option value="length">Length</option> 
                        <option value="name">Name</option>
                        {/* Додайте інші опції сортування за потребою */}
                    </select>
                </div>
                
                {/* Підрахунок часу */}
                <button 
                    onClick={handleCountTotalTime} 
                    className="count-time-button"
                >
                    Count total time
                </button>
                <p>Total Time: **{totalTime}**</p>
            </div>
            {/* ------------------------------------------- */}

            {/* --- ВІДОБРАЖЕННЯ СПИСКУ ФІЛЬМІВ --- */}
            <h3>Films Library ({films.length} items)</h3>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '20px' }}>
                {films.map(film => (
                    // Використовуємо компонент, який ми написали раніше
                    <FilmCard key={film.id} film={film} />
                ))}
            </div>
            {/* ------------------------------------- */}
        </div>
    );
}

export default FilmGallery;
